def add(a, b):
    return a + b


def mul(a, b):
    return a * b


def div(a, b):
    return a / b


def sub(a, b):
    return a - b

from collections import Counter


def mean(xs):
    values = list(xs)
    if not values:
        raise ValueError("mean is undefined for an empty sequence")
    return sum(values) / len(values)


def median(xs):
    values = sorted(xs)
    if not values:
        raise ValueError("median is undefined for an empty sequence")

    middle = len(values) // 2
    if len(values) % 2:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2


def mode(xs):
    counts = Counter(xs)
    if not counts:
        raise ValueError("mode is undefined for an empty sequence")
    return counts.most_common(1)[0][0]
